import{_ as e,o as a,c as s,ag as r,j as o}from"./chunks/framework.KxDd3USm.js";const _=JSON.parse('{"title":"05.1 进程、线程与状态转换 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"05-操作系统/01-进程线程与状态.md","filePath":"05-操作系统/01-进程线程与状态.md"}'),n={name:"05-操作系统/01-进程线程与状态.md"},d={class:"fig"},l={"data-figure-id":"figure-30",viewBox:"0 0 720 300",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"进程三态转换图。就绪经调度进入运行；运行因时间片到或被抢占回到就绪；运行请求 I/O 或等待事件进入阻塞；阻塞在 I/O 完成或事件发生后回到就绪。图中特别标出就绪不能直接变阻塞，阻塞不能直接变运行。"};function i(p,t,h,u,g,q){return a(),s("div",null,[t[2]||(t[2]=r(`<h1 id="_05-1-进程、线程与状态转换-★★★" tabindex="-1">05.1 进程、线程与状态转换 ★★★ <a class="header-anchor" href="#_05-1-进程、线程与状态转换-★★★" aria-label="Permalink to &quot;05.1 进程、线程与状态转换 ★★★&quot;">​</a></h1><h3 id="为什么要有进程" tabindex="-1">为什么要有进程 <a class="header-anchor" href="#为什么要有进程" aria-label="Permalink to &quot;为什么要有进程&quot;">​</a></h3><p>程序是躺在我盘上的代码文件（静态），但系统里同时跑着浏览器、播放器、输入法——每个&quot;正在执行的程序副本&quot;就是一个<strong>进程</strong>（动态）。进程 = 程序的一次执行过程，由创建而产生、完成任务后撤销而消亡。<strong>进程是系统进行资源分配和调度的独立单位</strong>。</p><p>进程由三部分组成：<strong>程序块 + 数据块 + 进程控制块 PCB</strong>。</p><table tabindex="0"><thead><tr><th>组成部分</th><th>作用</th></tr></thead><tbody><tr><td>程序块</td><td>要执行的代码</td></tr><tr><td>数据块</td><td>处理的数据</td></tr><tr><td><strong>PCB</strong></td><td>进程的&quot;身份证 + 档案袋&quot;：进程标识符、状态、现场保护区、队列指针等</td></tr></tbody></table><p><strong>PCB 是进程存在的唯一标志</strong>——系统根本&quot;看不见&quot;程序，它只认 PCB。创建进程 = 建 PCB，撤销进程 = 撤 PCB。这是选择题直接考的一句话。</p><h3 id="线程-进程内部的-分工" tabindex="-1">线程：进程内部的&quot;分工&quot; <a class="header-anchor" href="#线程-进程内部的-分工" aria-label="Permalink to &quot;线程：进程内部的&quot;分工&quot;&quot;">​</a></h3><p>进程是资源分配单位，但切换进程开销大，于是把&quot;调度&quot;下放到更小的单位——<strong>线程</strong>。线程是处理机调度的基本单位，同一进程内的多个线程共享进程的资源。</p><p><strong>共享 / 不共享（必背）</strong>：</p><table tabindex="0"><thead><tr><th>同一进程的线程<strong>共享</strong></th><th>线程<strong>独有</strong></th></tr></thead><tbody><tr><td>进程的代码段、全局变量、堆、打开的文件、信号处理器</td><td><strong>栈</strong>（每个线程有自己的栈）、寄存器组、程序计数器</td></tr></tbody></table><p><strong>反例演示（易错）</strong>：题目爱问&quot;以下叙述错误的是&quot;——凡出现&quot;线程间共享<strong>栈 / 栈指针 / 寄存器</strong>&quot;必错；凡&quot;共享代码段 / 全局变量 / 打开的文件&quot;必对。记忆法：栈是各线程自己的&quot;私人工作台&quot;，代码和仓库（全局变量、文件）是整间办公室公用的。</p><p><strong>应试动作</strong>：背两句话——&quot;PCB 是进程存在的唯一标志&quot;；&quot;线程共享代码/全局数据/文件，独有栈和寄存器现场&quot;。考场上认特征词：题干说&quot;资源分配&quot;→ 进程，说&quot;调度/处理机&quot;→ 线程。</p><h2 id="第二节-进程状态转换-★★★-几乎每年-1-题" tabindex="-1">第二节 进程状态转换 ★★★（几乎每年 1 题） <a class="header-anchor" href="#第二节-进程状态转换-★★★-几乎每年-1-题" aria-label="Permalink to &quot;第二节 进程状态转换 ★★★（几乎每年 1 题）&quot;">​</a></h2><h3 id="为什么要有状态" tabindex="-1">为什么要有状态 <a class="header-anchor" href="#为什么要有状态" aria-label="Permalink to &quot;为什么要有状态&quot;">​</a></h3><p>CPU 只有一个，进程几十个，必须给每个进程贴个状态标签，调度器才知道&quot;谁在跑、谁能跑、谁在干等&quot;。三态模型：</p><ul><li><strong>运行</strong>：正在 CPU 上执行（单处理机上处于运行的进程<strong>只有一个</strong>）；</li><li><strong>就绪</strong>：万事俱备只欠 CPU——除 CPU 外什么资源都有了，排着队等调度；</li><li><strong>阻塞（等待/睡眠）</strong>：在等别的事件（如等 I/O 完成），<strong>就算给它 CPU 也跑不了</strong>。</li></ul><h3 id="三态转换图-必须能默写" tabindex="-1">三态转换图（必须能默写） <a class="header-anchor" href="#三态转换图-必须能默写" aria-label="Permalink to &quot;三态转换图（必须能默写）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>          调度（被选中）</span></span>
<span class="line"><span>  就绪 ────────────────→ 运行</span></span>
<span class="line"><span>   ↑  ←────────────────  │</span></span>
<span class="line"><span>   │      时间片到        │ 请求I/O等事件（主动等）</span></span>
<span class="line"><span>   │ 事件发生（I/O完成）   ↓</span></span>
<span class="line"><span>   └──────────────────  阻塞</span></span></code></pre></div>`,18)),o("figure",d,[(a(),s("svg",l,[...t[0]||(t[0]=[r('<defs><marker id="p-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><rect x="65" y="115" width="110" height="52" rx="18" class="state"></rect><text x="103" y="147" class="t">就绪</text><rect x="305" y="115" width="110" height="52" rx="18" class="state"></rect><text x="343" y="147" class="t">运行</text><rect x="545" y="115" width="110" height="52" rx="18" class="state"></rect><text x="583" y="147" class="t">阻塞</text><path d="M175 125H304" class="e" marker-end="url(#p-arrow)"></path><text x="211" y="111" class="s">调度（被选中）</text><path d="M305 157H176" class="e" marker-end="url(#p-arrow)"></path><text x="202" y="184" class="s">时间片到 / 被抢占</text><path d="M415 125H544" class="e" marker-end="url(#p-arrow)"></path><text x="445" y="111" class="s">请求 I/O、等事件</text><path d="M545 157H416" class="e" marker-end="url(#p-arrow)"></path><text x="450" y="184" class="s">I/O 完成、事件发生</text><path d="M110 105Q360 28 610 105" stroke="var(--red)" stroke-width="2" stroke-dasharray="6 5" fill="none"></path><text x="272" y="37" class="bad">× 就绪不能直接阻塞</text><path d="M610 177Q360 272 110 177" stroke="var(--red)" stroke-width="2" stroke-dasharray="6 5" fill="none"></path><text x="272" y="269" class="bad">× 阻塞不能直接运行，必须先回就绪</text>',19)])])),t[1]||(t[1]=o("figcaption",null,"所有“回来”的路径先到就绪；只有正在运行的进程才能主动请求等待。",-1))]),t[3]||(t[3]=r('<table tabindex="0"><thead><tr><th>转换</th><th>触发条件</th><th>可能吗</th></tr></thead><tbody><tr><td>就绪 → 运行</td><td>被调度程序选中</td><td>✓</td></tr><tr><td>运行 → 就绪</td><td><strong>时间片用完</strong>（或被更高优先级抢占）</td><td>✓</td></tr><tr><td>运行 → 阻塞</td><td>进程<strong>主动</strong>请求 I/O、等待某事件</td><td>✓</td></tr><tr><td>阻塞 → 就绪</td><td>等待的事件<strong>发生</strong>（如 I/O 完成）</td><td>✓</td></tr><tr><td>运行 → 阻塞 与 阻塞 → 运行 之外的组合见下</td><td></td><td></td></tr><tr><td><strong>就绪 → 阻塞</strong></td><td>——</td><td><strong>✗ 不可能</strong>（阻塞是&quot;运行中主动去等&quot;才会发生的，就绪的进程根本没在跑，没机会发起等待）</td></tr><tr><td><strong>阻塞 → 运行</strong></td><td>——</td><td><strong>✗ 不可能</strong>（事件发生后先进就绪队列排队，不能插队直接上 CPU）</td></tr></tbody></table><p><strong>公式三件套（判转换题的通用判据 + 算例 + 口诀）</strong>：</p><ul><li>判据：阻塞 → 运行必须经过<strong>就绪</strong>中转；就绪 → 阻塞不存在。</li><li>算例：进程 P 在运行中发出读盘请求 → 运行→阻塞；盘读完了 → 阻塞→就绪；轮到 P → 就绪→运行；P 时间片用完 → 运行→就绪。</li><li>口诀：<strong>&quot;运行一头两头堵&quot;</strong>——运行能去就绪（时间片到）也能去阻塞（等事件）；回来都得先到就绪，除了&quot;事件发生&quot;那条从阻塞回到就绪。</li></ul><p><strong>五态模型（了解）</strong>：三态基础上增加&quot;挂起&quot;——进程被换出到磁盘对换区（主存不足、故障调试时），活动就绪↔静止就绪、活动阻塞↔静止阻塞。记住：<strong>三态中的每一种都可能被挂起</strong>。</p><p><strong>应试动作</strong>：背死两个&quot;不可能&quot;（就绪→阻塞、阻塞→运行）；场景题对号入座——&quot;时间片到&quot;→运行→就绪，&quot;等 I/O&quot;→运行→阻塞，&quot;I/O 完成&quot;→阻塞→就绪，&quot;被调度选中&quot;→就绪→运行。</p>',5))])}const x=e(n,[["render",i]]);export{_ as __pageData,x as default};
